from redraw_proofs_c1 import Pen


def rects(d,text,r,s):
 for item in text.split(';'):
  if item.strip():d.r(tuple(map(int,item.split())),r,s)


def lines(d,text,r,s):
 for path in text.split(';'):
  if path.strip():d.l(path.strip(),r,s)


